  "shared/pedagogy/types.ts": "export type Domain =\n  | \"math\"\n  | \"science\"\n  | \"philosophy\"\n  | \"code\"\n  | \"law\"\n  | \"politics\"\n  | \"psychology\"\n  | \"medicine\"\n  | \"arts\"\n  | \"history\"\n  | \"general\";\n\nexport interface TopicDefinition {\n  slug: string;\n  title: string;\n  domain: Domain;\n  summary: string;\n  intuition: string[];\n  formalCore: string[];\n  prerequisites: string[];\n  misconceptions: string[];\n  examples: string[];\n  exercises: string[];\n  reflections: string[];\n  diagramNodes: string[];\n  formalism: number;\n  visualizable: boolean;\n  interdisciplinaryHooks: string[];\n}\n\nexport interface TeacherPolicy {\n  name: string;\n  analogyDensity: number;\n  socraticRatio: number;\n  formalism: number;\n  retrievalPractice: number;\n  exerciseCount: number;\n  diagramBias: number;\n  reflectionBias: number;\n  interdisciplinaryBias: number;\n  challengeRate: number;\n}\n\nexport interface SimulationWeights {\n  masteryGain: number;\n  retention: number;\n  engagement: number;\n  transfer: number;\n  confusion: number;\n}\n\nexport interface LearnerProfile {\n  id: string;\n  /** Optional learner-stated biography, studies, interests and prior experience; data, not instructions. */\n  background?: string;\n  priorKnowledge: number;\n  abstractionComfort: number;\n  analogyNeed: number;\n  dialoguePreference: number;\n  diagramAffinity: number;\n  persistence: number;\n  transferDesire: number;\n  anxiety: number;\n}\n\nexport interface BenchmarkMeasurement {\n  /** Null means unmeasured, rather than a measured failure. */\n  value: number | null;\n  source: \"observed\" | \"proxy\" | \"unavailable\";\n  sampleSize: number;\n  note: string;\n}\n\nexport interface RetrospectiveBenchmarkEvidence {\n  kind: \"retrospective\";\n  scoringRule: \"assessment-mean-or-feedback-proxy-v1\";\n  score: BenchmarkMeasurement;\n  assessmentPerformance: BenchmarkMeasurement;\n  metrics: Record<keyof SimulationWeights, BenchmarkMeasurement>;\n  feedbackCounts: { explicit: number; inferred: number; unclassified: number };\n  /** Re-scoring historical records cannot validate an unexecuted candidate. */\n  eligibleForPromotion: false;\n}\n\nexport interface TeachingSimulation {\n  learner: LearnerProfile;\n  topic: TopicDefinition;\n  masteryGain: number;\n  retention: number;\n  engagement: number;\n  transfer: number;\n  confusion: number;\n  score: number;\n  breakdown: {\n    intuitionFit: number;\n    rigorFit: number;\n    dialogueFit: number;\n    diagramFit: number;\n    practiceFit: number;\n    reflectionFit: number;\n    overload: number;\n  };\n  explanation: string[];\n  /** Authoritative availability for retrospective records; legacy scalars use zero for unknown. */\n  evidence?: RetrospectiveBenchmarkEvidence;\n}\n\nexport interface TopicBenchmark {\n  topic: TopicDefinition;\n  learnerCount: number;\n  meanScore: number;\n  meanMasteryGain: number;\n  meanRetention: number;\n  meanEngagement: number;\n  meanTransfer: number;\n  meanConfusion: number;\n  topLearners: TeachingSimulation[];\n  strugglingLearners: TeachingSimulation[];\n  dominantStrength: string;\n  dominantWeakness: string;\n  evidence?: RetrospectiveBenchmarkEvidence;\n}\n\nexport interface BenchmarkTopicTrace {\n  topic: string;\n  topLearners: Array<{\n    learnerId: string;\n    score: number;\n    explanation: string[];\n  }>;\n  strugglingLearners: Array<{\n    learnerId: string;\n    score: number;\n    explanation: string[];\n  }>;\n  metricMeans: {\n    masteryGain: number;\n    retention: number;\n    engagement: number;\n    transfer: number;\n    confusion: number;\n  };\n  dominantStrength: string;\n  dominantWeakness: string;\n  evidence?: RetrospectiveBenchmarkEvidence;\n}\n\nexport interface BenchmarkTrace {\n  seed: number;\n  learnerCountPerTopic: number;\n  topicTraces: BenchmarkTopicTrace[];\n  realOutcomeCount: number;\n  syntheticFallback: boolean;\n  dataSource?: \"learner-feedback\" | \"learner-feedback-sparse\" | \"synthetic\" | \"no-learner-feedback\";\n  evaluationMode?: \"retrospective\" | \"synthetic\";\n  eligibleForPromotion?: boolean;\n}\n\nexport interface BenchmarkResult {\n  policy: TeacherPolicy;\n  suiteName: string;\n  topicBenchmarks: TopicBenchmark[];\n  overallScore: number;\n  weakestTopic: string;\n  trace: BenchmarkTrace;\n}\n\nexport interface LessonPhase {\n  id: string;\n  title: string;\n  purpose: string;\n  bullets: string[];\n}\n\nexport interface LessonPlan {\n  topic: TopicDefinition;\n  policy: TeacherPolicy;\n  phases: LessonPhase[];\n}\n\nexport interface CandidateDecision {\n  improves: boolean;\n  safe: boolean;\n  novelEnough: boolean;\n  scoreDelta: number;\n  weakestTopicDelta: number;\n  reasons: string[];\n}\n\nexport interface PolicyDelta {\n  field: keyof TeacherPolicy;\n  before: number | string;\n  after: number | string;\n  delta: number;\n}\n\nexport interface EvolutionCandidate {\n  policy: TeacherPolicy;\n  benchmark: BenchmarkResult;\n  counterfactualBenchmark?: BenchmarkResult;\n  parentName: string | null;\n  iteration: number;\n  novelty: number;\n  accepted: boolean;\n  decision: CandidateDecision;\n  parameterDelta: PolicyDelta[];\n  preferenceScore?: number;\n}\n\nexport interface PromptObjectiveVector {\n  voice_divergence: number;\n  diagnosis: number;\n  verification: number;\n  retrieval: number;\n  transfer: number;\n  structure: number;\n}\n\nexport interface EngagementPolicy {\n  name: string;\n  /** Retention half-life in days at mastery=1.0. */\n  retentionHalfLifeDays: number;\n  /** Threshold below which a topic is due for review. */\n  dueThreshold: number;\n  /** Minimum days between reviews even if retention is low. */\n  minReviewIntervalDays: number;\n  /** Urgency tiers: critical, high, moderate, and low day thresholds. */\n  urgencyTiers: [number, number, number, number];\n}\n\nexport interface MapElitesCell {\n  policy: TeacherPolicy;\n  weights: SimulationWeights;\n  score: number;\n  benchmark: BenchmarkResult;\n  iteration: number;\n}\n\nexport interface MapElitesGrid {\n  descriptors: string[];\n  resolution: number;\n  cells: Map<string, MapElitesCell | null>;\n}\n\nexport interface MapElitesRun {\n  baseline: BenchmarkResult;\n  best: BenchmarkResult;\n  grid: MapElitesGrid;\n  filledCellCount: number;\n  totalCells: number;\n  exploredCandidates: EvolutionCandidate[];\n}\n\nexport interface LearnerTurnSignal {\n  topic: string;\n  signal: \"thumbs-up\" | \"thumbs-down\" | \"confused\";\n  masteryEstimate: number;\n  evidence: string;\n}\n\nexport interface PolicyJudgementCandidate {\n  label: string;\n  policy: TeacherPolicy;\n  benchmark: BenchmarkResult;\n  counterfactualBenchmark?: BenchmarkResult;\n  preferenceScore: number;\n}\n\nexport interface QuizLimits {\n  questionChars: number;\n  answerChars: number;\n  explanationChars: number;\n  rubricChars: number;\n  optionChars: number;\n}\n\nexport interface QuizReview {\n  status: \"passed\" | \"revised\";\n  issues: string[];\n  duplicatesRemoved: number;\n  maxQuestionChars: number;\n  maxAnswerChars: number;\n  maxExplanationChars: number;\n  maxRubricChars: number;\n  maxOptionChars: number;\n  limits: QuizLimits;\n}\n",
