  "src/core/skate-secrets.ts": "import { spawnSync } from \"node:child_process\";\n\n/**\n * Resolve a secret from the `skate` CLI (charmbracelet key-value store).\n * Names may target a db with the `key@db` form, e.g. \"minimax@secrets\".\n * Returns undefined when skate is missing, exits non-zero, or holds no value.\n */\nexport function resolveSkateSecret(name: string): string | undefined {\n  try {\n    const result = spawnSync(\"skate\", [\"get\", name], { encoding: \"utf8\" });\n    if (result.status !== 0) return undefined;\n    const value = result.stdout.trim();\n    return value.length > 0 ? value : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\n/**\n * The MiniMax key used by the e2e harness: env var first, then the\n * shared Skate secrets db. Never throws.\n */\nexport function resolveMinimaxApiKey(): string | undefined {\n  return process.env.MINIMAX_API_KEY || resolveSkateSecret(\"minimax@secrets\");\n}\n",
  "src/core/speech.js": "\"use strict\";\nObject.defineProperty(exports, \"__esModule\", { value: true });\nexports.VOICE_TAGS = exports.KEATING_VOICE_TOOL_NAME = void 0;\nexports.normalizeVoiceUtterance = normalizeVoiceUtterance;\nexports.voiceTagLine = voiceTagLine;\nexports.speechStrategySummary = speechStrategySummary;\nexports.KEATING_VOICE_TOOL_NAME = \"keating_voice\";\nexports.VOICE_TAGS = [\n    \"explain\",\n    \"question\",\n    \"verify\",\n    \"redirect\",\n    \"encourage\",\n    \"pause\",\n    \"recap\"\n];\nconst DEFAULT_TAGS = [\"explain\"];\nconst DEFAULT_PACE = \"normal\";\nconst DEFAULT_AFFECT = \"warm\";\nfunction isVoiceTag(value) {\n    return exports.VOICE_TAGS.includes(value);\n}\nfunction cleanText(value) {\n    return String(value ?? \"\").replace(/\\s+/g, \" \").trim();\n}\nfunction normalizeVoiceUtterance(input, speech) {\n    const text = cleanText(input.text);\n    if (!text) {\n        throw new Error(\"keating_voice requires non-empty text.\");\n    }\n    const tags = (input.tags ?? [])\n        .map(tag => cleanText(tag).toLowerCase())\n        .filter(isVoiceTag);\n    return {\n        text,\n        voice: cleanText(input.voice) || speech.defaultVoice,\n        tags: tags.length > 0 ? tags : DEFAULT_TAGS,\n        pace: input.pace ?? DEFAULT_PACE,\n        affect: input.affect ?? DEFAULT_AFFECT,\n        listenFor: input.listenFor ? cleanText(input.listenFor) : undefined\n    };\n}\nfunction voiceTagLine(utterance) {\n    const attrs = [\n        `voice=${utterance.voice}`,\n        `tags=${utterance.tags.join(\",\")}`,\n        `pace=${utterance.pace}`,\n        `affect=${utterance.affect}`,\n        utterance.listenFor ? `listen_for=${utterance.listenFor}` : undefined\n    ].filter(Boolean);\n    return `[voice ${attrs.join(\" \")}] ${utterance.text}`;\n}\nfunction speechStrategySummary(speech) {\n    return [\n        `speech=${speech.enabled ? \"enabled\" : \"disabled\"}`,\n        `voice=${speech.defaultVoice}`,\n        `fast_model=${speech.fastModel ?? \"unset\"}`,\n        `steering_model=${speech.steeringModel ?? \"default\"}`\n    ].join(\"\\n\");\n}\n",
  "src/core/speech.ts": "import type { KeatingConfig } from \"./config.js\";\n\nexport const KEATING_VOICE_TOOL_NAME = \"keating_voice\";\n\nexport const VOICE_TAGS = [\n  \"explain\",\n  \"question\",\n  \"verify\",\n  \"redirect\",\n  \"encourage\",\n  \"pause\",\n  \"recap\"\n] as const;\n\nexport type VoiceTag = (typeof VOICE_TAGS)[number];\n\ntype Pace = \"slow\" | \"normal\" | \"quick\";\ntype Affect = \"warm\" | \"curious\" | \"firm\" | \"celebratory\";\n\nexport interface VoiceUtterance {\n  text: string;\n  voice: string;\n  tags: VoiceTag[];\n  pace: Pace;\n  affect: Affect;\n  listenFor?: string;\n}\n\nexport type VoiceUtteranceInput = Partial<Omit<VoiceUtterance, \"text\">> & {\n  text: string;\n  tags?: string[];\n};\n\nconst DEFAULT_TAGS: VoiceTag[] = [\"explain\"];\nconst DEFAULT_PACE: VoiceUtterance[\"pace\"] = \"normal\";\nconst DEFAULT_AFFECT: VoiceUtterance[\"affect\"] = \"warm\";\n\nfunction isVoiceTag(value: string): value is VoiceTag {\n  return (VOICE_TAGS as readonly string[]).includes(value);\n}\n\nfunction cleanText(value: unknown): string {\n  return String(value ?? \"\").replace(/\\s+/g, \" \").trim();\n}\n\nexport function normalizeVoiceUtterance(\n  input: VoiceUtteranceInput,\n  speech: KeatingConfig[\"speech\"]\n): VoiceUtterance {\n  const text = cleanText(input.text);\n  if (!text) {\n    throw new Error(\"keating_voice requires non-empty text.\");\n  }\n\n  const tags = (input.tags ?? [])\n    .map(tag => cleanText(tag).toLowerCase())\n    .filter(isVoiceTag);\n\n  return {\n    text,\n    voice: cleanText(input.voice) || speech.defaultVoice,\n    tags: tags.length > 0 ? tags : DEFAULT_TAGS,\n    pace: input.pace ?? DEFAULT_PACE,\n    affect: input.affect ?? DEFAULT_AFFECT,\n    listenFor: input.listenFor ? cleanText(input.listenFor) : undefined\n  };\n}\n\nexport function voiceTagLine(utterance: VoiceUtterance): string {\n  const attrs = [\n    `voice=${utterance.voice}`,\n    `tags=${utterance.tags.join(\",\")}`,\n    `pace=${utterance.pace}`,\n    `affect=${utterance.affect}`,\n    utterance.listenFor ? `listen_for=${utterance.listenFor}` : undefined\n  ].filter(Boolean);\n\n  return `[voice ${attrs.join(\" \")}] ${utterance.text}`;\n}\n\nexport function speechStrategySummary(speech: KeatingConfig[\"speech\"]): string {\n  return [\n    `speech=${speech.enabled ? \"enabled\" : \"disabled\"}`,\n    `voice=${speech.defaultVoice}`,\n    `fast_model=${speech.fastModel ?? \"unset\"}`,\n    `steering_model=${speech.steeringModel ?? \"default\"}`\n  ].join(\"\\n\");\n}\n",
  "src/core/teaching-evolution.js": "\"use strict\";\nObject.defineProperty(exports, \"__esModule\", { value: true });\nexports.teachingEvolutionArtifact = teachingEvolutionArtifact;\nexports.teachingBenchmarkArtifact = teachingBenchmarkArtifact;\nasync function teachingEvolutionArtifact(_cwd, _options = {}) {\n    throw new Error(\"host-execution-unavailable\");\n}\nasync function teachingBenchmarkArtifact(_cwd, _options = {}) {\n    throw new Error(\"host-execution-unavailable\");\n}\n",
