  "web/src/keating/tool-result.js": "\"use strict\";\nObject.defineProperty(exports, \"__esModule\", { value: true });\nexports.MISSING_TOOL_RESULT_MESSAGE = void 0;\nexports.hasMeaningfulToolResult = hasMeaningfulToolResult;\nexports.toolExecutionSucceeded = toolExecutionSucceeded;\nexports.MISSING_TOOL_RESULT_MESSAGE = \"Tool execution ended without returning a result.\";\nfunction hasMeaningfulToolResult(value) {\n    if (value === undefined || value === null)\n        return false;\n    if (typeof value === \"string\")\n        return value.trim().length > 0;\n    if (Array.isArray(value))\n        return value.length > 0;\n    if (typeof value === \"object\")\n        return Object.keys(value).length > 0;\n    return true;\n}\nfunction toolExecutionSucceeded(event) {\n    return event.isError !== true && hasMeaningfulToolResult(event.result);\n}\n",
