export const NODEPOD_BOOT_FILE_COUNT = 553;

/** For a given .ts path, return its transpiled .js counterpart if it exists. */
export function getJsCounterpart(tsPath: string): string | null {
  const jsPath = tsPath.replace(/\.ts$/, ".js");
  return NODEPOD_BOOT_FILES[jsPath] ? jsPath : null;
}

